import fs from "node:fs";
import path from "node:path";

const root = process.cwd();

function fail(message) {
  console.error("\nERROR:", message);
  process.exit(1);
}

if (!fs.existsSync(path.join(root, "pnpm-workspace.yaml"))) {
  fail("Uruchom z głównego katalogu aplikacja-turnieje-live.");
}

const required = [
  "artifacts/animated-effects/AE_PACK_06.json",
  "artifacts/animated-effects/src/main.ts",
  "artifacts/animated-effects/src/style.css",
  "artifacts/animated-effects/src/effects/registry.ts",
  "artifacts/animated-effects/src/effects/variants.ts",
  "artifacts/animated-effects/src/effects/effectModules.ts",
];

for (const rel of required) {
  if (!fs.existsSync(path.join(root, rel))) {
    fail("Brak wymaganego pliku: " + rel);
  }
}

const stylePath = path.join(
  root,
  "artifacts/animated-effects/src/style.css",
);

const style = fs.readFileSync(
  stylePath,
  "utf8",
);

if (style.includes("AE_PACK_06_POLISH_02_START")) {
  console.log("Pack 06 Polish 02 jest już zainstalowany.");
  process.exit(0);
}

const stamp = new Date()
  .toISOString()
  .replace(/[:.]/g, "-")
  .replace("T", "_")
  .replace("Z", "");

const backupRoot = path.join(
  root,
  ".ae-pack-backup",
  "pack-06-polish-02-" + stamp,
);

const payload = {"artifacts/animated-effects/src/effects/modules/pack06Extra.ts": "", "artifacts/animated-effects/src/effects/modules/pack06ExtraVariants.ts": "", "artifacts/animated-effects/src/pack06/polish02.ts": ""};

const touched = [
  ...Object.keys(payload),
  "artifacts/animated-effects/src/main.ts",
  "artifacts/animated-effects/src/style.css",
  "artifacts/animated-effects/src/effects/registry.ts",
  "artifacts/animated-effects/src/effects/variants.ts",
  "artifacts/animated-effects/src/effects/effectModules.ts",
];

const existed = [];

for (const rel of touched) {
  const source = path.join(root, rel);

  if (!fs.existsSync(source)) {
    continue;
  }

  existed.push(rel);

  const target = path.join(
    backupRoot,
    rel,
  );

  fs.mkdirSync(
    path.dirname(target),
    { recursive:true },
  );

  fs.copyFileSync(
    source,
    target,
  );
}

fs.mkdirSync(
  backupRoot,
  { recursive:true },
);

fs.writeFileSync(
  path.join(
    backupRoot,
    "backup-manifest.json",
  ),
  JSON.stringify(
    {
      existed,
      touched,
    },
    null,
    2,
  ),
);

for (const [rel, value] of Object.entries(payload)) {
  const target = path.join(root, rel);

  fs.mkdirSync(
    path.dirname(target),
    { recursive:true },
  );

  fs.writeFileSync(
    target,
    Buffer.from(value, "base64"),
  );
}

const registryPath = path.join(
  root,
  "artifacts/animated-effects/src/effects/registry.ts",
);

let registry = fs.readFileSync(
  registryPath,
  "utf8",
);

if (!registry.includes("pack06ExtraEffectModules")) {
  const pack06ImportPattern =
    /import\s*\{\s*pack06EffectModules\s*,?\s*\}\s*from\s*["']\.\/modules\/pack06["']\s*;?/m;

  const importMatch =
    registry.match(pack06ImportPattern);

  if (!importMatch) {
    fail(
      "Nie znaleziono importu pack06EffectModules w registry.ts. " +
      "Instalator nie zmienił registry.ts."
    );
  }

  registry = registry.replace(
    pack06ImportPattern,
    `${importMatch[0]}

import {
  pack06ExtraEffectModules,
} from "./modules/pack06Extra";`,
  );

  const moduleListPattern =
    /(\.\.\.effectModules\s*,\s*\.\.\.pack06EffectModules\s*,?)/m;

  if (!moduleListPattern.test(registry)) {
    fail(
      "Nie znaleziono listy allEffectModules z Pack 06 w registry.ts."
    );
  }

  registry = registry.replace(
    moduleListPattern,
    `$1
    ...pack06ExtraEffectModules,`,
  );
}

fs.writeFileSync(
  registryPath,
  registry,
  "utf8",
);

const variantsPath = path.join(
  root,
  "artifacts/animated-effects/src/effects/variants.ts",
);

let variants = fs.readFileSync(
  variantsPath,
  "utf8",
);

if (!variants.includes("pack06ExtraVariantCatalog")) {
  const variantImportPattern =
    /import\s*\{\s*pack06EffectVariantCatalog\s*,?\s*\}\s*from\s*["']\.\/modules\/pack06Variants["']\s*;?/m;

  const variantImportMatch =
    variants.match(variantImportPattern);

  if (!variantImportMatch) {
    fail(
      "Nie znaleziono importu pack06EffectVariantCatalog w variants.ts."
    );
  }

  variants = variants.replace(
    variantImportPattern,
    `${variantImportMatch[0]}

import {
  pack06ExtraVariantCatalog,
} from "./modules/pack06ExtraVariants";`,
  );

  const returnPattern =
    /return\s+pack06EffectVariantCatalog\[effectId\]\s*\?\?\s*effectVariantCatalog\[effectId\]\s*\?\?\s*\[\]\s*;/m;

  if (!returnPattern.test(variants)) {
    fail(
      "Nie znaleziono zwrotu getEffectVariants() dla Pack 06."
    );
  }

  variants = variants.replace(
    returnPattern,
    "return pack06ExtraVariantCatalog[effectId] ?? pack06EffectVariantCatalog[effectId] ?? effectVariantCatalog[effectId] ?? [];",
  );
}

fs.writeFileSync(
  variantsPath,
  variants,
  "utf8",
);

const mainPath = path.join(
  root,
  "artifacts/animated-effects/src/main.ts",
);

let main = fs.readFileSync(
  mainPath,
  "utf8",
);

if (!main.includes('from "./pack06/polish02"')) {
  const installImportPattern =
    /import\s*\{\s*installPack06\s*,?\s*\}\s*from\s*["']\.\/pack06\/install["']\s*;?/m;

  const installImportMatch =
    main.match(installImportPattern);

  if (!installImportMatch) {
    fail(
      "Nie znaleziono importu installPack06 w main.ts."
    );
  }

  main = main.replace(
    installImportPattern,
    `${installImportMatch[0]}

import {
  installPack06Polish02,
} from "./pack06/polish02";`,
  );
}

if (!main.includes("installPack06Polish02();")) {
  const callPattern =
    /installPack06\s*\(\s*\)\s*;?/m;

  if (!callPattern.test(main)) {
    fail(
      "Nie znaleziono wywołania installPack06() w main.ts."
    );
  }

  main = main.replace(
    callPattern,
    (match) =>
      `${match}
installPack06Polish02();`,
  );
}

fs.writeFileSync(
  mainPath,
  main,
  "utf8",
);

const modulesPath = path.join(
  root,
  "artifacts/animated-effects/src/effects/effectModules.ts",
);

let modules = fs.readFileSync(
  modulesPath,
  "utf8",
);

const start = modules.indexOf(
  "const meteorShowerCss = `",
);

const end = modules.indexOf(
  "`.trim();",
  start,
);

if (start < 0 || end < 0) {
  fail("Nie znaleziono meteorShowerCss.");
}

modules =
  modules.slice(0, start) +
  "const meteorShowerCss = `\n.ae-meteor {\n  position: absolute;\n  width: var(--ae-meteor-size, 140px);\n  height: 3px;\n  border-radius: 999px;\n  background: linear-gradient(\n    90deg,\n    transparent 0%,\n    rgba(95,120,255,.08) 24%,\n    rgba(125,215,255,.46) 64%,\n    rgba(235,250,255,.92) 88%,\n    #fff 100%\n  );\n  box-shadow:\n    0 0 10px rgba(155,225,255,.42),\n    0 0 24px rgba(110,150,255,.22);\n  transform-origin: center;\n  animation: ae-meteor var(--ae-meteor-duration, 3.2s) linear infinite;\n  will-change: transform, opacity;\n}\n.ae-meteor::after {\n  content: \"\";\n  position: absolute;\n  right: -2px;\n  top: 50%;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  transform: translateY(-50%);\n  background: #fff;\n  box-shadow:\n    0 0 8px rgba(255,255,255,.95),\n    0 0 18px rgba(120,220,255,.72);\n}\n@keyframes ae-meteor {\n  0% {\n    transform:\n      translate3d(-28vw,-34vh,0)\n      rotate(38deg);\n    opacity: 0;\n  }\n  8% { opacity: 1; }\n  88% { opacity: .95; }\n  100% {\n    transform:\n      translate3d(118vw,108vh,0)\n      rotate(38deg);\n    opacity: 0;\n  }\n}\n`.trim();" +
  modules.slice(
    end + "`.trim();".length,
  );

modules = modules
  .replaceAll(
    'meteor.style.left = `${random() * 36}%`;',
    'meteor.style.left = `${-12 + random() * 78}%`;',
  )
  .replaceAll(
    'meteor.style.top = `${random() * 36}%`;',
    'meteor.style.top = `${-18 + random() * 24}%`;',
  )
  .replaceAll(
    'meteor.style.left = random() * 36 + "%";',
    'meteor.style.left = (-12 + random() * 78) + "%";',
  )
  .replaceAll(
    'meteor.style.top = random() * 36 + "%";',
    'meteor.style.top = (-18 + random() * 24) + "%";',
  );


// Accept both compact and formatted Pack 05 source.
modules = modules
  .replace(
    /meteor\.style\.left\s*=\s*`\$\{random\(\)\s*\*\s*36\}%`\s*;/g,
    'meteor.style.left = `${-12 + random() * 78}%`;',
  )
  .replace(
    /meteor\.style\.top\s*=\s*`\$\{random\(\)\s*\*\s*36\}%`\s*;/g,
    'meteor.style.top = `${-18 + random() * 24}%`;',
  )
  .replace(
    /meteor\.style\.left\s*=\s*random\(\)\s*\*\s*36\s*\+\s*"%"\s*;/g,
    'meteor.style.left = (-12 + random() * 78) + "%";',
  )
  .replace(
    /meteor\.style\.top\s*=\s*random\(\)\s*\*\s*36\s*\+\s*"%"\s*;/g,
    'meteor.style.top = (-18 + random() * 24) + "%";',
  );

fs.writeFileSync(
  modulesPath,
  modules,
  "utf8",
);

fs.writeFileSync(
  stylePath,
  style.trimEnd() +
    "\n\n" +
    "\n/* === AE_PACK_06_POLISH_02_START === */\n\n@media (min-width:1500px) {\n  .ae-editor-grid {\n    grid-template-columns:\n      350px minmax(0,1fr) 370px;\n  }\n}\n\n.ae-preview-shell {\n  padding:16px 18px;\n}\n\n.ae-effect-filters {\n  grid-template-columns:\n    repeat(3,minmax(0,1fr));\n  gap:7px;\n}\n\n.ae-effect-filters .ae-search-wrap {\n  grid-column:1/-1;\n}\n\n.ae-polish02-card {\n  min-height:62px;\n  grid-template-columns:\n    26px minmax(0,1fr) auto;\n  gap:7px;\n}\n\n.ae-polish02-card\n  .ae-pack06-favorite {\n  width:26px;\n  height:40px;\n  border-radius:8px;\n}\n\n.ae-polish02-card\n  .ae-pack06-favorite:hover {\n  background:rgba(255,255,255,.045);\n  color:#f2c96f;\n}\n\n.ae-polish02-card\n  .ae-pack06-card-actions {\n  gap:4px;\n}\n\n.ae-polish02-card\n  .ae-pack06-minus,\n.ae-polish02-card\n  .ae-pack06-count,\n.ae-polish02-card\n  .ae-add-icon {\n  min-width:34px;\n  width:34px;\n  height:36px;\n  border-radius:8px;\n}\n\n.ae-polish02-card\n  .ae-pack06-count {\n  color:#91ddff;\n  font-size:11px;\n  font-weight:850;\n}\n\n.ae-polish02-card.is-on-scene {\n  box-shadow:\n    inset 3px 0 0 rgba(87,199,255,.78);\n}\n\n.ae-pack06-scene-badge {\n  display:none !important;\n}\n\n.ae-polish02-header {\n  display:flex;\n  align-items:center;\n  gap:7px;\n}\n\n.ae-polish02-direct {\n  display:flex;\n  gap:5px;\n}\n\n.ae-polish02-direct .ae-button {\n  min-width:40px;\n  padding:0 10px;\n}\n\n.ae-polish02-menu {\n  position:relative;\n}\n\n.ae-polish02-menu > summary {\n  min-height:38px;\n  display:flex;\n  align-items:center;\n  gap:7px;\n  padding:0 12px;\n  border:1px solid var(--ae-line-strong);\n  border-radius:10px;\n  background:#141a25;\n  color:#d7dfed;\n  font-size:10.5px;\n  font-weight:750;\n  cursor:pointer;\n  list-style:none;\n}\n\n.ae-polish02-menu > summary::-webkit-details-marker {\n  display:none;\n}\n\n.ae-polish02-menu-panel {\n  position:absolute;\n  z-index:60;\n  top:calc(100% + 8px);\n  right:0;\n  width:220px;\n  display:grid;\n  gap:7px;\n  padding:9px;\n  border:1px solid var(--ae-line-strong);\n  border-radius:12px;\n  background:#101722;\n  box-shadow:0 18px 60px rgba(0,0,0,.5);\n}\n\n.ae-polish02-menu-panel\n  .ae-button,\n.ae-polish02-menu-panel\n  .ae-category-select {\n  width:100%;\n}\n\n.ae-polish02-inspector\n  .ae-inspector-content {\n  padding:13px 14px 18px;\n}\n\n.ae-polish02-inspector\n  .inspector-title {\n  position:sticky;\n  z-index:8;\n  top:0;\n  margin:0 0 12px;\n  padding:12px 13px;\n  background:\n    linear-gradient(\n      135deg,\n      rgba(124,92,255,.14),\n      rgba(124,92,255,.045)\n    ),\n    #101620;\n  backdrop-filter:blur(8px);\n}\n\n.ae-polish02-inspector\n  .inspector-group {\n  margin-bottom:10px;\n  padding:13px 13px 5px;\n  border-color:rgba(255,255,255,.085);\n}\n\n.ae-polish02-inspector\n  input:not([type=\"range\"]):not([type=\"color\"]),\n.ae-polish02-inspector select {\n  min-height:36px;\n  width:100%;\n  border:1px solid rgba(255,255,255,.11);\n  border-radius:9px;\n  padding:0 10px;\n  outline:none;\n  background:#111824;\n  color:#edf3ff;\n}\n\n.ae-polish02-inspector\n  input:not([type=\"range\"]):not([type=\"color\"]):focus,\n.ae-polish02-inspector select:focus {\n  border-color:rgba(124,92,255,.58);\n  box-shadow:0 0 0 3px rgba(124,92,255,.08);\n}\n\n.ae-media-dialog {\n  width:min(980px,94vw);\n}\n\n.ae-media-export {\n  display:grid;\n  gap:12px;\n  padding:14px 16px 18px;\n  overflow-y:auto;\n  max-height:calc(88vh - 68px);\n}\n\n.ae-polish02-output,\n.ae-polish02-media-card {\n  margin:0;\n  padding:14px;\n  border:1px solid rgba(255,255,255,.085) !important;\n  border-radius:13px;\n  background:\n    linear-gradient(\n      180deg,\n      rgba(255,255,255,.024),\n      rgba(255,255,255,.008)\n    );\n}\n\n.ae-polish02-card-heading {\n  display:grid;\n  gap:3px;\n  margin-bottom:10px;\n}\n\n.ae-polish02-card-heading strong,\n.ae-polish02-media-card h3 {\n  margin:0;\n  color:#f2f6ff;\n  font-size:13px;\n}\n\n.ae-polish02-card-heading span,\n.ae-polish02-description {\n  margin:3px 0 12px;\n  color:#718096;\n  font-size:10px;\n  line-height:1.45;\n}\n\n.ae-polish02-presets {\n  display:flex;\n  flex-wrap:wrap;\n  gap:6px;\n  margin-bottom:12px;\n}\n\n.ae-polish02-presets button {\n  min-height:30px;\n  padding:0 10px;\n  border:1px solid rgba(255,255,255,.1);\n  border-radius:8px;\n  background:#151d2a;\n  color:#b9c5d7;\n  font-size:9.5px;\n  font-weight:700;\n}\n\n.ae-polish02-presets button:hover {\n  border-color:rgba(124,92,255,.48);\n  color:#ece8ff;\n}\n\n.ae-media-dialog .ae-media-grid {\n  grid-template-columns:\n    repeat(auto-fit,minmax(155px,1fr));\n  gap:10px;\n}\n\n.ae-media-dialog .ae-media-grid label {\n  color:#9dabbd;\n  font-size:9.5px;\n  font-weight:650;\n}\n\n.ae-media-dialog\n  .ae-media-grid input,\n.ae-media-dialog\n  .ae-media-grid select {\n  min-height:38px;\n  width:100%;\n  border:1px solid rgba(255,255,255,.11);\n  border-radius:9px;\n  padding:0 10px;\n  outline:none;\n  background:#101722;\n  color:#edf3ff;\n}\n\n.ae-media-dialog\n  .ae-media-grid input[type=\"color\"] {\n  padding:4px;\n}\n\n.ae-media-dialog input:disabled {\n  opacity:.42;\n}\n\n.ae-polish02-summary {\n  display:flex;\n  align-items:baseline;\n  justify-content:space-between;\n  gap:12px;\n  margin:2px 0 12px;\n  padding:10px 11px;\n  border-radius:9px;\n  background:rgba(124,92,255,.07);\n}\n\n.ae-polish02-summary strong {\n  color:#eeeaff;\n  font-size:11px;\n}\n\n.ae-polish02-summary span {\n  color:#7f8ca1;\n  font-size:9.5px;\n}\n\n.ae-media-dialog progress {\n  height:10px;\n  overflow:hidden;\n  border:0;\n  border-radius:999px;\n  background:#151d2a;\n}\n\n.ae-media-dialog\n  progress::-webkit-progress-value {\n  background:\n    linear-gradient(90deg,#6750e6,#65c9ff);\n}\n\n.ae-gif-preview[hidden],\n[data-gif-save][hidden],\n[data-cancel-gif][hidden] {\n  display:none !important;\n}\n\n@media (max-width:1260px) {\n  .ae-effect-filters {\n    grid-template-columns:1fr;\n  }\n\n  .ae-effect-filters\n    .ae-search-wrap {\n    grid-column:auto;\n  }\n}\n\n/* === AE_PACK_06_POLISH_02_END === */\n".trim() +
    "\n",
  "utf8",
);

const rollbackPath = path.join(
  root,
  "ae-pack-06-polish-02-rollback.mjs",
);

const rollback =
`import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const backupRoot = ${JSON.stringify(backupRoot)};
const manifest = JSON.parse(
  fs.readFileSync(
    path.join(backupRoot, "backup-manifest.json"),
    "utf8"
  )
);
const existed = new Set(manifest.existed);

for (const rel of manifest.touched) {
  const target = path.join(root, rel);
  const source = path.join(backupRoot, rel);

  if (existed.has(rel)) {
    fs.mkdirSync(path.dirname(target), { recursive:true });
    fs.copyFileSync(source, target);
  } else {
    fs.rmSync(target, { recursive:true, force:true });
  }
}

console.log("Pack 06 Polish 02 cofnięty.");
`;

fs.writeFileSync(
  rollbackPath,
  rollback,
  "utf8",
);

